import React from 'react';
import { useNavigate } from 'react-router-dom';

export default function Dashboard() {
  const navigate = useNavigate();
  const storedUser = localStorage.getItem('user');
  const user = storedUser ? JSON.parse(storedUser) : null;

  const logout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    navigate('/login');
  };

  return (
    <div style={styles.page}>
      <div style={styles.container}>
        <div style={styles.headerRow}>
          <div>
            <h1 style={styles.title}>HealthyMe Pro Dashboard</h1>
            <p style={styles.subtitle}>
              {user ? `Welcome back, ${user.name}.` : 'Welcome to your health dashboard.'}
            </p>
          </div>
          <button type="button" onClick={logout} style={styles.logoutButton}>
            Logout
          </button>
        </div>

        <div style={styles.buttonGrid}>
          <button type="button" style={styles.actionButton} onClick={() => navigate('/predict')}>
            Predict Health Score
          </button>
          <button type="button" style={styles.actionButton} onClick={() => navigate('/history')}>
            View History
          </button>
          <button type="button" style={styles.actionButton} onClick={() => navigate('/chat')}>
            Open Chatbot
          </button>
        </div>
      </div>
    </div>
  );
}

const styles = {
  page: {
    minHeight: '100vh',
    background: 'linear-gradient(145deg, #eef7f0 0%, #d7ede0 100%)',
    padding: '32px 20px',
    fontFamily: 'Segoe UI, sans-serif',
  },
  container: {
    maxWidth: '980px',
    margin: '0 auto',
    background: '#ffffff',
    borderRadius: '24px',
    padding: '32px',
    boxShadow: '0 16px 40px rgba(32, 84, 61, 0.12)',
  },
  headerRow: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    gap: '16px',
    flexWrap: 'wrap',
    marginBottom: '28px',
  },
  title: {
    margin: '0 0 8px',
    color: '#1f4d3b',
  },
  subtitle: {
    margin: 0,
    color: '#658374',
  },
  buttonGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
    gap: '18px',
  },
  actionButton: {
    minHeight: '140px',
    border: 'none',
    borderRadius: '20px',
    background: 'linear-gradient(135deg, #1f7a55 0%, #2d8b63 100%)',
    color: '#ffffff',
    fontSize: '18px',
    fontWeight: 700,
    cursor: 'pointer',
    padding: '24px',
  },
  logoutButton: {
    border: 'none',
    borderRadius: '12px',
    background: '#eaf5ef',
    color: '#1f4d3b',
    padding: '12px 16px',
    cursor: 'pointer',
    fontWeight: 700,
  },
};
